class Solution { string expression;int position=0;array<int,2> combine(array<int,2> left,array<int,2> right,char op){array<int,2> result={1000000,1000000};for(int a=0;a<2;++a)for(int b=0;b<2;++b)for(char used:string("&|")){int value=used=='&'?(a&b):(a|b);result[value]=min(result[value],left[a]+right[b]+(used==op?0:1));}return result;}array<int,2> atom(){char current=expression[position];if(current=='('){++position;auto value=parse();++position;return value;}++position;return current=='0'?array<int,2>{0,1}:array<int,2>{1,0};}array<int,2> parse(){auto value=atom();while(position<(int)expression.size()&&expression[position]!=')'){char op=expression[position++];value=combine(value,atom(),op);}return value;}public: int minOperationsToFlip(string input){expression=input;position=0;auto cost=parse();return cost[0]==0?cost[1]:cost[0];} };
